func TestEnumWebhookEvent(t *testing.T) {
	t.Run("NewFromString_message_status", func(t *testing.T) {
		t.Parallel()
		val, err := NewWebhookEventFromString("message.status")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, WebhookEvent("message.status"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_message_delivered", func(t *testing.T) {
		t.Parallel()
		val, err := NewWebhookEventFromString("message.delivered")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, WebhookEvent("message.delivered"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_message_failed", func(t *testing.T) {
		t.Parallel()
		val, err := NewWebhookEventFromString("message.failed")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, WebhookEvent("message.failed"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_message_received", func(t *testing.T) {
		t.Parallel()
		val, err := NewWebhookEventFromString("message.received")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, WebhookEvent("message.received"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_broadcast_updated", func(t *testing.T) {
		t.Parallel()
		val, err := NewWebhookEventFromString("broadcast.updated")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, WebhookEvent("broadcast.updated"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewWebhookEventFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewWebhookEventFromString("message.status")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

func TestExtraPropertiesWebhookSubscription(t *testing.T) {
	t.Run("GetExtraProperties", func(t *testing.T) {
		t.Parallel()
		obj := &WebhookSubscription{}
		// Should not panic when calling GetExtraProperties()
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("GetExtraProperties() panicked: %v", r)
			}
		}()
		extraProps := obj.GetExtraProperties()
		// Result can be nil or an empty/non-empty map
		_ = extraProps
	})

	t.Run("GetExtraProperties_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *WebhookSubscription
		extraProps := obj.GetExtraProperties()
		assert.Nil(t, extraProps, "nil receiver should return nil without panicking")
	})
}
